package ca.stewark.helioflux.core.data.parser

import org.junit.Assert.*
import org.junit.Test

class SolarActivityParsersTest {
 @Test fun flareProbabilityTakesMaximaAfterClassCHeader(){ val r=FlareProbabilityParser.parse("# other\n1 99 99 99 x\n# Class C M X\nA 20 5 1 x\nB 40 2 0 x");assertEquals(40,r.c);assertEquals(5,r.m);assertEquals(1,r.x)}
 @Test fun xrayMergesNullsAndSorts(){val j="""[{"time_tag":"2026-09-19T12:01:00Z","satellite":19,"energy":"0.1-0.8nm","flux":2.0},{"time_tag":"2026-09-19T12:00:00Z","satellite":18,"energy":"0.05-0.4nm","flux":-1},{"time_tag":"2026-09-19T12:00:00Z","satellite":19,"energy":"0.05-0.4nm","flux":1.0}]""";val r=XrayFluxParser.parse(j);assertEquals(2,r.size);assertNull(r[0].goes18Short);assertEquals(1.0,r[0].goes19Short!!,0.0);assertTrue(r[0].timestampMillis<r[1].timestampMillis)}
 @Test fun donkiFlareFallbackRegionInstrumentAndOrdering(){val j="""[{"flrID":"a","beginTime":"2026-09-19T10:00:00","classType":"M1","activeRegionNum":14353,"sourceLocation":"N10W20","instruments":[{"displayName":"GOES-19 XRS"}]},{"flrID":"b","peakTime":"2026-09-19T11:00:00","classType":"X1","instruments":[]},{"flrID":"bad"}]""";val r=DonkiFlareParser.parse(j);assertEquals(listOf("b","a"),r.map{it.id});assertEquals("4353",r[1].region);assertEquals("GOES-19",r[1].observatory);assertEquals("N10W20",r[1].location)}
 @Test fun donkiCmeFallbackDirectionAndFields(){val j="""[{"associatedCMEID":"c","time21_5":"2026-09-19T10:00:00","speed":900,"halfAngle":45,"latitude":-10,"longitude":20,"type":"C","associatedCMELink":"link"},{"bad":1}]""";val r=DonkiCmeParser.parse(j).single();assertEquals("10.0°S 20.0°E",r.direction);assertEquals(900.0,r.speed!!,0.0);assertEquals(45.0,r.halfAngle!!,0.0)}
 @Test fun aceIswaCsvChannelsUnitsSortingAndWindow(){val csv="""time (yyyy-MM-dd'T'HH:mm:ss'Z'),ElectronFlux_38_53 (particles/cm2-s-ster-MeV),ElectronFlux_175_315 (particles/cm2-s-ster-MeV),ProtonFlux_47_68 (particles/cm2-s-ster-MeV),ProtonFlux_115_195 (particles/cm2-s-ster-MeV),ProtonFlux_310_580 (particles/cm2-s-ster-MeV),ProtonFlux_795_1193 (particles/cm2-s-ster-MeV),ProtonFlux_1060_1900 (particles/cm2-s-ster-MeV)
2026-09-19T12:05:00Z,1805.0,16.5,4.0,5.0,6.0,0.4,0.08
2026-09-19T12:00:00Z,1832.0,12.4,8.0,,9.0,0.3,-100000.0""";val r=AceEpamParser.parse(csv);assertEquals(2,r.size);assertTrue(r[0].timestampMillis<r[1].timestampMillis);assertEquals(8.0,r[0].protonLow!!,0.0);assertNull(r[0].protonMid);assertEquals(9.0,r[0].protonHigh!!,0.0);assertEquals(0.3,r[0].protonFp6!!,0.0);assertNull(r[0].protonP7);assertEquals(0.08,r[1].protonP7!!,0.0);assertEquals(2,AceEpamParser.last72Hours(r,r.last().timestampMillis).size)}
 @Test fun activeRegionFiltersDedupesAndFormats(){val j="""{"result":[{"ar_noaanum":"14353","hpc_x":10,"hpc_y":20},{"ar_noaanum":"14353","hpc_x":30,"hpc_y":40},{"ar_noaanum":"","hpc_x":1,"hpc_y":2},{"ar_noaanum":"999","hpc_x":1000,"hpc_y":2}]}""";val r=ActiveRegionParser.parse(j).single();assertEquals("4353",r.number);assertEquals(30.0,r.helioprojectiveX,0.0)}
 @Test fun enlilNewestRunSortsAndDownsamples(){val files=(0 until 60).joinToString(""){i->"<a href=\"enlil_com2_2_20260919T"+String.format("%02d",i/60)+"1200"+String.format("%02d",i%60)+".jpg\">x</a>"};val old="<a href=\"enlil_com2_1_20260918T120000.jpg\">x</a>";val r=EnlilListingParser.parse(old+files,"https://x/enlil");assertTrue(r.size<=48);assertTrue(r.zipWithNext().all{it.first.frameTimestampMillis<=it.second.frameTimestampMillis});assertTrue(r.all{it.url.contains("enlil_com2_2_")})}
}
